{
  "name": "stockcoaster",
  "version": "1.0.0",
  "description": "Ride the stock market. Literally. A Minecraft-like rollercoaster game where tracks are real stock charts.",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "data": "node data-pipeline/build-data.mjs"
  },
  "dependencies": {
    "three": "^0.165.0"
  },
  "devDependencies": {
    "playwright": "^1.60.0",
    "vite": "^5.4.0"
  }
}

import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
const OUT = '/Users/nwparker/orca/workspaces/stockcoaster/v1/test/shots/';

await page.goto('http://localhost:5179/?ride=NVDA&go=1', { waitUntil: 'networkidle' });
await page.waitForTimeout(2000);
const before = (await page.textContent('#hud-date'))?.trim().slice(0, 20);

// click at ~85% across the minimap chart
const box = await page.locator('#hud-chart').boundingBox();
const x85 = box.x + box.width * 0.85, ymid = box.y + box.height / 2;
await page.mouse.move(x85, ymid);           // hover first (scrubber line + date)
await page.waitForTimeout(400);
await page.screenshot({ path: OUT + '11-seek-hover.png', clip: { x: box.x - 12, y: box.y - 40, width: box.width + 40, height: box.height + 60 } });
await page.mouse.click(x85, ymid);
await page.waitForTimeout(1500);
const after = (await page.textContent('#hud-date'))?.trim().slice(0, 20);
const zone = (await page.textContent('#hud-zone'))?.trim();
console.log('before:', JSON.stringify(before), '-> after click @85%:', JSON.stringify(after), '| zone:', zone);
await page.screenshot({ path: OUT + '12-seek-result.png' });

// jump BACK to ~10%
await page.mouse.click(box.x + box.width * 0.10, ymid);
await page.waitForTimeout(1500);
console.log('after click @10%:', JSON.stringify((await page.textContent('#hud-date'))?.trim().slice(0, 20)));

// seek must also work from the pause overlay (ESC then click map)
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
await page.mouse.click(box.x + box.width * 0.5, ymid);
await page.waitForTimeout(1200);
const overlayGone = await page.evaluate(() => document.getElementById('lock-hint').style.display !== 'flex');
console.log('after ESC + map click @50%:', JSON.stringify((await page.textContent('#hud-date'))?.trim().slice(0, 20)), '| overlay dismissed:', overlayGone);

console.log('pageerrors:', errors.length ? errors : 'none');
await browser.close();

import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('https://stockcoaster.vercel.app', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
console.log('ride cards:', await page.locator('.ride-card').count());
await page.goto('https://stockcoaster.vercel.app/?ride=NVDA&go=1', { waitUntil: 'networkidle' });
await page.waitForTimeout(5000);
console.log('riding:', (await page.textContent('#hud-date'))?.trim().slice(0, 20), '|', (await page.textContent('#hud-zone'))?.trim());
await page.screenshot({ path: '/Users/nwparker/orca/workspaces/stockcoaster/v1/test/shots/13-production.png' });
console.log('pageerrors:', errors.length ? errors : 'none');
await browser.close();

import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
const OUT = '/Users/nwparker/orca/workspaces/stockcoaster/v1/test/shots/';

// NVDA near the end: should be OUTER SPACE (stars, moon, planets)
await page.goto('http://localhost:5179/?ride=NVDA&go=1&at=0.93', { waitUntil: 'networkidle' });
await page.waitForTimeout(4000);
console.log('NVDA @93%:', (await page.textContent('#hud-zone'))?.trim(), '|', (await page.textContent('#hud-date'))?.trim().slice(0,20));
await page.screenshot({ path: OUT + '07-nvda-space.png' });

// GME at the squeeze peak (~Jan 2021 is around 28% through 2019-2026)
await page.goto('http://localhost:5179/?ride=GME&go=1&at=0.27', { waitUntil: 'networkidle' });
await page.waitForTimeout(4000);
console.log('GME @27%:', (await page.textContent('#hud-zone'))?.trim(), '|', (await page.textContent('#hud-date'))?.trim().slice(0,20));
await page.screenshot({ path: OUT + '08-gme-squeeze.png' });

// PTON near the end: deep in THE PIT
await page.goto('http://localhost:5179/?ride=PTON&go=1&at=0.8', { waitUntil: 'networkidle' });
await page.waitForTimeout(4000);
console.log('PTON @80%:', (await page.textContent('#hud-zone'))?.trim(), '|', (await page.textContent('#hud-date'))?.trim().slice(0,20));
await page.screenshot({ path: OUT + '09-pton-pit.png' });

// ride to the end: summary screen
await page.goto('http://localhost:5179/?ride=BTC-USD&go=1&at=0.985', { waitUntil: 'networkidle' });
await page.waitForTimeout(8000);
const summary = await page.textContent('#summary-title').catch(() => null);
console.log('BTC summary title:', JSON.stringify(summary));
await page.screenshot({ path: OUT + '10-summary.png' });

console.log('pageerrors:', errors.length ? errors : 'none');
await browser.close();

// Headless smoke test: loads the menu, rides two coasters, captures
// screenshots + console errors. Run with the dev server up on :5179:
//   node test/smoke.mjs
import { chromium } from 'playwright';
import { mkdir } from 'node:fs/promises';

const BASE = process.env.BASE_URL ?? 'http://localhost:5179';
const OUT = new URL('../test/shots/', import.meta.url).pathname;
await mkdir(OUT, { recursive: true });

const browser = await chromium.launch({
  headless: true,
  args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });

const errors = [];
page.on('console', msg => {
  if (msg.type() === 'error' || msg.type() === 'warning') {
    errors.push(`[${msg.type()}] ${msg.text()}`);
  }
});
page.on('pageerror', e => errors.push(`[pageerror] ${e.message}`));

const fail = msg => { console.error('FAIL:', msg); process.exitCode = 1; };

// ---- 1. menu
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForTimeout(1200);
const cards = await page.locator('.ride-card').count();
console.log(`menu: ${cards} ride cards`);
if (cards < 10) fail(`expected >=10 ride cards, got ${cards}`);
await page.screenshot({ path: OUT + '01-menu.png' });

// ---- 2. NVDA ride via autostart param
await page.goto(BASE + '/?ride=NVDA&go=1', { waitUntil: 'networkidle' });
await page.waitForTimeout(2500);
const date1 = await page.textContent('#hud-date');
console.log('NVDA date @2.5s:', JSON.stringify(date1?.trim().slice(0, 30)));
await page.screenshot({ path: OUT + '02-nvda-start.png' });

await page.waitForTimeout(9000);
const date2 = await page.textContent('#hud-date');
console.log('NVDA date @11.5s:', JSON.stringify(date2?.trim().slice(0, 30)));
await page.screenshot({ path: OUT + '03-nvda-later.png' });
if (date1 === date2) fail('HUD date did not advance — cart appears stuck');

// speed up to 4 and jump ahead for the high-altitude part
await page.keyboard.press('Digit4');
await page.waitForTimeout(20000);
await page.screenshot({ path: OUT + '04-nvda-high.png' });
const zone = await page.textContent('#hud-zone');
console.log('NVDA zone @31s:', JSON.stringify(zone?.trim()));

// ---- 3. GME ride (meme theme, the squeeze)
await page.goto(BASE + '/?ride=GME&go=1', { waitUntil: 'networkidle' });
await page.keyboard.press('Digit3');
await page.waitForTimeout(12000);
await page.screenshot({ path: OUT + '05-gme.png' });
const gmeDate = await page.textContent('#hud-date');
console.log('GME date @12s:', JSON.stringify(gmeDate?.trim().slice(0, 30)));

// ---- 4. PTON (rust theme)
await page.goto(BASE + '/?ride=PTON&go=1', { waitUntil: 'networkidle' });
await page.waitForTimeout(6000);
await page.screenshot({ path: OUT + '06-pton.png' });

// ---- console errors
const uniq = [...new Set(errors)];
console.log(`\nconsole errors/warnings (${uniq.length}):`);
for (const e of uniq.slice(0, 30)) console.log(' ', e.slice(0, 300));

await browser.close();
console.log('\nscreenshots in', OUT);

