// Altitude bands: as the track (= log price) climbs, the world changes around you.
// sampleAtmosphere(y) interpolates sky/fog/lighting between bands.
import * as THREE from 'three';

export const GROUND_Y = 20;          // nominal terrain surface height
export const CAVE_Y = GROUND_Y - 3;  // track below this carves a lava trench
export const CLOUD_Y = 195;          // blocky cloud layer altitude
export const SPACE_Y = 300;

// [altitude, zone label, sky color, fog color, fog far, sun intensity, ambient intensity]
const BANDS = [
  [-10, 'THE PIT',          '#27060a', '#3a0d08', 70,   0.25, 0.5],
  [16,  'THE PIT',          '#43130f', '#552012', 110,  0.4,  0.55],
  [24,  'GREEN PLAINS',     '#7fb8ff', '#cfe5ff', 520,  1.0,  0.75],
  [70,  'THE FOOTHILLS',    '#74a9f5', '#c2dbf7', 560,  1.0,  0.72],
  [125, 'ALPINE HEIGHTS',   '#5f8fe0', '#a9c4ea', 620,  1.05, 0.68],
  [185, 'CLOUD LAYER',      '#4a6fc4', '#ffffff', 420,  1.1,  0.78],
  [225, 'STRATOSPHERE',     '#2b3a86', '#7d8fd0', 760,  1.0,  0.6],
  [275, 'EDGE OF SPACE',    '#141a4a', '#2a3060', 900,  0.9,  0.5],
  [320, 'OUTER SPACE',      '#04040c', '#070716', 1400, 0.8,  0.45],
];

const ZONE_ICONS = {
  'THE PIT': '🕳️', 'GREEN PLAINS': '🌿', 'THE FOOTHILLS': '🌲',
  'ALPINE HEIGHTS': '🏔️', 'CLOUD LAYER': '☁️', 'STRATOSPHERE': '🎈',
  'EDGE OF SPACE': '🌠', 'OUTER SPACE': '🌌',
};

const _sky = new THREE.Color(), _fog = new THREE.Color();
const _a = new THREE.Color(), _b = new THREE.Color();

export function sampleAtmosphere(y) {
  let i = 0;
  while (i < BANDS.length - 1 && y > BANDS[i + 1][0]) i++;
  const cur = BANDS[i];
  const next = BANDS[Math.min(i + 1, BANDS.length - 1)];
  const span = Math.max(1e-6, next[0] - cur[0]);
  const t = cur === next ? 0 : THREE.MathUtils.clamp((y - cur[0]) / span, 0, 1);

  _a.set(cur[2]); _b.set(next[2]); _sky.copy(_a).lerp(_b, t);
  _a.set(cur[3]); _b.set(next[3]); _fog.copy(_a).lerp(_b, t);

  // Label flips halfway through the transition.
  const label = t < 0.5 ? cur[1] : next[1];
  return {
    sky: _sky, fog: _fog,
    fogFar: THREE.MathUtils.lerp(cur[4], next[4], t),
    sun: THREE.MathUtils.lerp(cur[5], next[5], t),
    ambient: THREE.MathUtils.lerp(cur[6], next[6], t),
    label,
    icon: ZONE_ICONS[label] ?? '',
    starAlpha: THREE.MathUtils.clamp((y - 215) / 90, 0, 1),
    spaceness: THREE.MathUtils.clamp((y - 255) / 80, 0, 1),
  };
}

// Converts a price series into a 3D coaster track.
//  - altitude = log-scaled price (so a 7000x run reads as cave -> space)
//  - the path meanders laterally so it feels like a coaster, not a chart
//  - blocky rails/ties/supports built from instanced boxes
import * as THREE from 'three';
import { groundHeight } from './terrain.js';
import { lambert } from './textures.js';

export const POINT_SPACING = 6;
const UP = new THREE.Vector3(0, 1, 0);
export const Y_BASE = 12;

export function buildTrackData(ride, theme) {
  const pts = ride.points;
  const n = pts.length;

  let logMin = Infinity, logMax = -Infinity;
  for (const p of pts) {
    const l = Math.log(p.close);
    if (l < logMin) logMin = l;
    if (l > logMax) logMax = l;
  }
  const logSpan = Math.max(1e-9, logMax - logMin);
  const multiple = Math.exp(logSpan);
  const ySpanMult = theme?.launchDay ? 3.4 : (theme?.rockets ? 1.25 : 1.0); // IPO launch days + meme stocks get extra altitude
  const minSpan = theme?.launchDay ? 225 : 70;
  const ySpan = THREE.MathUtils.clamp(95 * Math.log10(multiple) * ySpanMult, minSpan, 318);

  // Raw altitudes, then two smoothing passes: keeps the macro chart shape but
  // turns per-bar volatility sawtooth into rideable hills. HUD prices stay raw.
  let ys = [];
  for (let i = 0; i < n; i++) {
    const p = (Math.log(pts[i].close) - logMin) / logSpan;
    ys.push(Y_BASE + Math.pow(p, 1.12) * ySpan);
  }
  for (let pass = 0; pass < 2; pass++) {
    const t = ys.slice();
    for (let i = 1; i < n - 1; i++) ys[i] = 0.25 * t[i - 1] + 0.5 * t[i] + 0.25 * t[i + 1];
  }

  const controlPoints = [];
  const meta = [];
  let runningMax = -Infinity;
  for (let i = 0; i < n; i++) {
    const c = pts[i].close;
    const p = (Math.log(c) - logMin) / logSpan;
    const x = i * POINT_SPACING;
    const y = ys[i];
    const z = 34 * Math.sin(x * 0.0045 + 1.7) + 14 * Math.sin(x * 0.013 + 0.5);
    controlPoints.push(new THREE.Vector3(x, y, z));

    const prevMax = runningMax;
    runningMax = Math.max(runningMax, c);
    meta.push({
      normPrice: p,
      drawdown: prevMax > 0 ? Math.max(0, 1 - c / prevMax) : 0,
      isATH: c >= runningMax && i > 0,
      gain: i > 0 ? c / pts[i - 1].close - 1 : 0,
      trench: false, // filled in below once we know ground height
    });
  }
  for (let i = 0; i < n; i++) {
    const cp = controlPoints[i];
    meta[i].trench = cp.y < groundHeight(cp.x, cp.z, ride.symbol) + 2.5;
  }

  // ATH parties: a new all-time high only deserves confetti after a real dip
  // (>=15% drawdown since the previous high), plus the ride's absolute peak.
  let ddSinceATH = 0;
  for (let i = 1; i < n; i++) {
    if (meta[i].isATH) {
      meta[i].athParty = ddSinceATH >= 0.15;
      ddSinceATH = 0;
    } else {
      ddSinceATH = Math.max(ddSinceATH, meta[i].drawdown);
      meta[i].athParty = false;
    }
  }
  meta[0].athParty = false;
  if (ride.stats?.maxIndex > 0) meta[ride.stats.maxIndex].athParty = true;

  const curve = new THREE.CatmullRomCurve3(controlPoints, false, 'centripetal', 0.5);
  curve.arcLengthDivisions = Math.max(2000, n * 12);
  const length = curve.getLength();

  // u (arc-length param 0..1) at each control point, for sign placement & HUD.
  const divs = curve.arcLengthDivisions;
  const lengths = curve.getLengths(divs);
  const total = lengths[lengths.length - 1];
  const uAtPoint = [];
  for (let i = 0; i < n; i++) {
    const t = i / (n - 1);
    const j = Math.min(divs, Math.round(t * divs));
    uAtPoint.push(lengths[j] / total);
  }

  // Precomputed frame table: position, tangent, lateral, up (with banking).
  const samples = Math.max(600, n * 6);
  const frames = sampleFrames(curve, samples);

  return { ride, pts, controlPoints, meta, curve, length, uAtPoint, frames, ySpan, samples };
}

function sampleFrames(curve, samples) {
  const pos = [], tan = [], lat = [], up = [];
  let prevLat = null;
  for (let i = 0; i <= samples; i++) {
    const u = i / samples;
    const p = curve.getPointAt(u);
    const t = curve.getTangentAt(u);
    let l;
    if (prevLat === null) {
      l = new THREE.Vector3().crossVectors(t, UP);
      if (l.lengthSq() < 1e-6) l.set(0, 0, 1);
      l.normalize();
    } else {
      // Parallel transport, then bleed accumulated roll back toward horizontal.
      l = prevLat.clone().addScaledVector(t, -prevLat.dot(t));
      if (l.lengthSq() < 1e-6) l = prevLat.clone();
      l.y *= 0.82;
      l.normalize();
    }
    prevLat = l;
    pos.push(p); tan.push(t); lat.push(l);
    up.push(new THREE.Vector3().crossVectors(l, t).normalize());
  }
  // Banking: roll into turns based on yaw rate, smoothed.
  const bank = new Float32Array(samples + 1);
  for (let i = 1; i < samples; i++) {
    const a = Math.atan2(tan[i - 1].z, tan[i - 1].x);
    const b = Math.atan2(tan[i + 1].z, tan[i + 1].x);
    let d = b - a;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    bank[i] = THREE.MathUtils.clamp(d * 6, -0.55, 0.55);
  }
  for (let pass = 0; pass < 3; pass++) {
    for (let i = 1; i < samples; i++) bank[i] = (bank[i - 1] + bank[i] + bank[i + 1]) / 3;
  }
  const q = new THREE.Quaternion();
  for (let i = 0; i <= samples; i++) {
    if (Math.abs(bank[i]) > 1e-4) {
      q.setFromAxisAngle(tan[i], bank[i]);
      lat[i].applyQuaternion(q);
      up[i].applyQuaternion(q);
    }
  }
  return { pos, tan, lat, up };
}

/** Interpolated frame at arc-length parameter u in [0,1]. Writes into `out`. */
export function frameAt(track, u, out) {
  const { pos, tan, lat, up } = track.frames;
  const f = THREE.MathUtils.clamp(u, 0, 1) * track.samples;
  const i0 = Math.min(track.samples - 1, Math.floor(f));
  const i1 = i0 + 1;
  const t = f - i0;
  out.pos.lerpVectors(pos[i0], pos[i1], t);
  out.tan.lerpVectors(tan[i0], tan[i1], t).normalize();
  out.lat.lerpVectors(lat[i0], lat[i1], t).normalize();
  out.up.lerpVectors(up[i0], up[i1], t).normalize();
  return out;
}

export function makeFrame() {
  return { pos: new THREE.Vector3(), tan: new THREE.Vector3(), lat: new THREE.Vector3(), up: new THREE.Vector3() };
}

/** Data point index nearest to arc parameter u (for HUD date/price). */
export function pointIndexAtU(track, u) {
  const arr = track.uAtPoint;
  let lo = 0, hi = arr.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] < u) lo = mid + 1; else hi = mid;
  }
  if (lo > 0 && Math.abs(arr[lo - 1] - u) < Math.abs(arr[lo] - u)) lo--;
  return lo;
}

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _s = new THREE.Vector3();
const _basis = new THREE.Matrix4();
const _negLat = new THREE.Vector3();

function setInstance(mesh, idx, pos, tanV, latV, upV, scale) {
  // lat/up/tan from sampleFrames form a LEFT-handed triple (lat×up = -tan);
  // negate the lateral so the basis is a pure rotation, or the quaternion
  // extraction degenerates and every rail/tie renders world-axis-aligned.
  _basis.makeBasis(_negLat.copy(latV).negate(), upV, tanV);
  _q.setFromRotationMatrix(_basis);
  _s.copy(scale);
  _m.compose(pos, _q, _s);
  mesh.setMatrixAt(idx, _m);
}

export function buildTrackMeshes(track, T, theme) {
  const group = new THREE.Group();
  const { pos, tan, lat, up } = track.frames;
  const S = track.samples;
  const box = new THREE.BoxGeometry(1, 1, 1);

  // --- rails: one small box per sample segment per side
  const railMat = lambert(T.iron);
  const rails = new THREE.InstancedMesh(box, railMat, S * 2);
  const segP = new THREE.Vector3(), segT = new THREE.Vector3(), segL = new THREE.Vector3(), segU = new THREE.Vector3();
  let ri = 0;
  for (let i = 0; i < S; i++) {
    const segLen = pos[i].distanceTo(pos[i + 1]) + 0.12;
    segP.addVectors(pos[i], pos[i + 1]).multiplyScalar(0.5);
    segT.subVectors(pos[i + 1], pos[i]).normalize();
    segL.addVectors(lat[i], lat[i + 1]).normalize();
    segU.addVectors(up[i], up[i + 1]).normalize();
    for (const side of [-1, 1]) {
      const p = segP.clone().addScaledVector(segL, side * 1.0).addScaledVector(segU, 0.12);
      setInstance(rails, ri++, p, segT, segL, segU, _s.set(0.3, 0.24, segLen));
    }
  }
  rails.count = ri;
  group.add(rails);

  // --- ties: planks every ~2 samples
  const tieCount = Math.ceil(S / 2);
  const ties = new THREE.InstancedMesh(box, lambert(T.planks), tieCount);
  let ti = 0;
  for (let i = 0; i < S; i += 2) {
    setInstance(ties, ti++, pos[i], tan[i], lat[i], up[i], _s.set(2.9, 0.22, 1.0));
  }
  ties.count = ti;
  group.add(ties);

  // --- support pillars: every 6th data point, stacked log blocks down to ground
  const pillarPositions = [];
  for (let i = 0; i < track.controlPoints.length; i += 6) {
    const cp = track.controlPoints[i];
    if (track.meta[i].trench) continue;
    const gy = groundHeight(cp.x, cp.z, track.ride.symbol);
    if (cp.y - gy < 3) continue;
    pillarPositions.push({ cp, gy });
  }
  let blockTotal = 0;
  for (const p of pillarPositions) blockTotal += Math.ceil((p.cp.y - 0.8 - p.gy) / 1.7) + 1;
  if (blockTotal > 0) {
    const pillars = new THREE.InstancedMesh(box, lambert(T.log), blockTotal);
    let pi = 0;
    for (const { cp, gy } of pillarPositions) {
      const topY = cp.y - 0.8;
      const count = Math.ceil((topY - gy) / 1.7) + 1;
      for (let k = 0; k < count; k++) {
        const y = Math.min(topY, gy + k * 1.7 + 0.85);
        _m.compose(
          _s.set(cp.x, y, cp.z).clone(),
          _q.identity(),
          new THREE.Vector3(1.5, 1.75, 1.5),
        );
        pillars.setMatrixAt(pi++, _m);
      }
    }
    pillars.count = pi;
    group.add(pillars);
  }

  group.traverse(o => { if (o.isInstancedMesh) { o.instanceMatrix.needsUpdate = true; o.frustumCulled = false; } });
  return group;
}

// Particle effects: ATH confetti, crash embers, alpine snow, space sparkles,
// rocket exhaust on monster green candles. One instanced-box pool, CPU updated.
import * as THREE from 'three';

const MAX = 700;
const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _s = new THREE.Vector3();
const _v = new THREE.Vector3();
const _c = new THREE.Color();

export class Effects {
  constructor(scene) {
    this.mesh = new THREE.InstancedMesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshBasicMaterial({ transparent: true }),
      MAX,
    );
    this.mesh.frustumCulled = false;
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    scene.add(this.mesh);
    this.scene = scene;

    this.parts = [];
    for (let i = 0; i < MAX; i++) {
      this.parts.push({
        alive: false,
        pos: new THREE.Vector3(), vel: new THREE.Vector3(),
        life: 0, maxLife: 1, size: 0.3, color: new THREE.Color(),
        gravity: 0, spin: Math.random() * 6,
      });
    }
    this.cursor = 0;
    this.snowAcc = 0;
    this.emberAcc = 0;
    this.sparkleAcc = 0;
  }

  /** IPO launch-show rockets: flame columns, smoke, and blocky fireworks above the rider. */
  launchShow(camPos, forwardDir) {
    const right = new THREE.Vector3(-forwardDir.z, 0, forwardDir.x).normalize();
    const base = camPos.clone()
      .addScaledVector(forwardDir, 95 + Math.random() * 70)
      .addScaledVector(right, (Math.random() < 0.5 ? -1 : 1) * (35 + Math.random() * 55));
    base.y = Math.max(camPos.y - 32, 18);
    const top = base.clone();
    top.y = camPos.y + 80 + Math.random() * 75;

    // The rising rocket trail: hot core with chunky white smoke falling behind it.
    for (let i = 0; i < 42; i++) {
      const k = i / 41;
      const p = base.clone().lerp(top, k);
      p.x += (Math.random() - 0.5) * (1 + k * 7);
      p.z += (Math.random() - 0.5) * (1 + k * 7);
      const hot = k > 0.72;
      this.spawn(
        p,
        new THREE.Vector3((Math.random() - 0.5) * 2, hot ? 8 + Math.random() * 8 : -1 - Math.random() * 2, (Math.random() - 0.5) * 2),
        hot ? (Math.random() < 0.55 ? 0xfde047 : 0xf97316) : (Math.random() < 0.55 ? 0xe5e7eb : 0x94a3b8),
        hot ? 0.34 : 0.48,
        hot ? 0.9 : 1.8,
        hot ? -4 : 0,
      );
    }

    // Blocky firework blossom.
    const colors = [0xf97316, 0xfde047, 0x60a5fa, 0xc4b5fd, 0xffffff, 0x4ade80];
    for (let i = 0; i < 115; i++) {
      _v.randomDirection().multiplyScalar(12 + Math.random() * 30);
      this.spawn(top, _v.clone(), colors[i % colors.length], 0.28, 1.0 + Math.random() * 1.0, -5);
    }
  }

  spawn(pos, vel, color, size, life, gravity = 0) {
    const p = this.parts[this.cursor];
    this.cursor = (this.cursor + 1) % MAX;
    p.alive = true;
    p.pos.copy(pos);
    p.vel.copy(vel);
    p.color.set(color);
    p.size = size;
    p.life = 0;
    p.maxLife = life;
    p.gravity = gravity;
  }

  /** Golden/green confetti explosion at an all-time high. */
  confetti(pos) {
    const colors = [0xfcd34d, 0x4ade80, 0xf472b6, 0x60a5fa, 0xfb923c, 0xffffff];
    for (let i = 0; i < 130; i++) {
      _v.randomDirection().multiplyScalar(6 + Math.random() * 16);
      _v.y = Math.abs(_v.y) + 6;
      this.spawn(pos, _v.clone(), colors[i % colors.length], 0.34, 1.6 + Math.random() * 1.4, -14);
    }
  }

  /** Green rocket exhaust behind the cart on big up-moves. */
  rocketBoost(pos, backDir) {
    for (let i = 0; i < 3; i++) {
      _v.copy(backDir).multiplyScalar(14 + Math.random() * 8);
      _v.x += (Math.random() - 0.5) * 5;
      _v.y += (Math.random() - 0.5) * 5;
      _v.z += (Math.random() - 0.5) * 5;
      this.spawn(pos, _v.clone(), Math.random() < 0.7 ? 0x4ade80 : 0xfde047, 0.26, 0.6, 0);
    }
  }

  /** Ambient weather around the camera, driven by altitude + drawdown. */
  ambient(dt, camPos, altY, drawdown, spaceness) {
    // snow in the alpine band
    if (altY > 120 && altY < 250) {
      this.snowAcc += dt * 26;
      while (this.snowAcc >= 1) {
        this.snowAcc -= 1;
        _v.set(camPos.x + (Math.random() - 0.5) * 80, camPos.y + 16 + Math.random() * 10, camPos.z + (Math.random() - 0.5) * 80);
        this.spawn(_v, new THREE.Vector3((Math.random() - 0.5) * 2, -7 - Math.random() * 3, (Math.random() - 0.5) * 2), 0xffffff, 0.22, 4.4, 0);
      }
    }
    // red embers when deep in a drawdown (crash sections)
    if (drawdown > 0.45) {
      this.emberAcc += dt * (10 + drawdown * 26);
      while (this.emberAcc >= 1) {
        this.emberAcc -= 1;
        _v.set(camPos.x + (Math.random() - 0.5) * 60, camPos.y - 8 + Math.random() * 8, camPos.z + (Math.random() - 0.5) * 60);
        this.spawn(_v, new THREE.Vector3((Math.random() - 0.5) * 3, 2.5 + Math.random() * 4, (Math.random() - 0.5) * 3),
          Math.random() < 0.6 ? 0xf97316 : 0xef4444, 0.17, 3.2, 0);
      }
    }
    // glittering stardust in space
    if (spaceness > 0.4) {
      this.sparkleAcc += dt * 14;
      while (this.sparkleAcc >= 1) {
        this.sparkleAcc -= 1;
        _v.set(camPos.x + (Math.random() - 0.5) * 70, camPos.y + (Math.random() - 0.5) * 40, camPos.z + (Math.random() - 0.5) * 70);
        this.spawn(_v, new THREE.Vector3(0, (Math.random() - 0.5) * 1.4, 0),
          Math.random() < 0.5 ? 0xc4b5fd : 0xe0f2fe, 0.16, 2.6, 0);
      }
    }
  }

  update(dt) {
    let count = 0;
    for (const p of this.parts) {
      if (!p.alive) continue;
      p.life += dt;
      if (p.life >= p.maxLife) { p.alive = false; continue; }
      p.vel.y += p.gravity * dt;
      p.pos.addScaledVector(p.vel, dt);
      const fade = 1 - p.life / p.maxLife;
      _q.setFromAxisAngle(_v.set(0.4, 0.8, 0.2).normalize(), p.spin + p.life * 5);
      _m.compose(p.pos, _q, _s.setScalar(p.size * (0.4 + 0.6 * fade)));
      this.mesh.setMatrixAt(count, _m);
      this.mesh.setColorAt(count, _c.copy(p.color));
      count++;
    }
    this.mesh.count = count;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
  }
}

// Procedural 16x16 pixel-art textures, Minecraft style. No external assets.
import * as THREE from 'three';

function makeCanvas(draw, size = 16) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  draw(ctx, size);
  const tex = new THREE.CanvasTexture(c);
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

// Deterministic PRNG so textures look the same every run.
function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function speckle(ctx, size, colors, seed = 1) {
  const r = rng(seed);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      ctx.fillStyle = colors[Math.floor(r() * colors.length)];
      ctx.fillRect(x, y, 1, 1);
    }
  }
}

export function buildTextures() {
  const T = {};

  // Near-white grass so InstancedMesh instanceColor can tint per biome/theme.
  T.grassTop = makeCanvas((ctx, s) => speckle(ctx, s, ['#ffffff', '#f2f2f2', '#e4e4e4', '#d6d6d6'], 7));
  T.dirt = makeCanvas((ctx, s) => speckle(ctx, s, ['#9b6a44', '#8a5d3b', '#7c5234', '#a8754d'], 11));
  T.grassSide = makeCanvas((ctx, s) => {
    speckle(ctx, s, ['#9b6a44', '#8a5d3b', '#7c5234', '#a8754d'], 13);
    const r = rng(5);
    for (let x = 0; x < s; x++) {
      const h = 3 + Math.floor(r() * 3);
      for (let y = 0; y < h; y++) {
        ctx.fillStyle = ['#ffffff', '#ececec', '#dcdcdc'][Math.floor(r() * 3)];
        ctx.fillRect(x, y, 1, 1);
      }
    }
  });
  T.stone = makeCanvas((ctx, s) => speckle(ctx, s, ['#8a8a8a', '#7d7d7d', '#919191', '#737373'], 17));
  T.deepRock = makeCanvas((ctx, s) => speckle(ctx, s, ['#4a3535', '#553b3b', '#3e2c2c', '#5e4040'], 19));
  T.lava = makeCanvas((ctx, s) => {
    speckle(ctx, s, ['#ff7b00', '#ff5200', '#ffa200', '#e63900'], 23);
    const r = rng(29);
    for (let i = 0; i < 9; i++) {
      ctx.fillStyle = '#ffe680';
      ctx.fillRect(Math.floor(r() * s), Math.floor(r() * s), 2, 1);
    }
  });
  T.sand = makeCanvas((ctx, s) => speckle(ctx, s, ['#e7d8a7', '#dbcb96', '#efe2b8', '#d2c188'], 31));
  T.snow = makeCanvas((ctx, s) => speckle(ctx, s, ['#ffffff', '#f1f5fb', '#e6ecf5'], 37));
  T.log = makeCanvas((ctx, s) => {
    const r = rng(41);
    for (let x = 0; x < s; x++) {
      const shade = ['#6b4a2a', '#5e4125', '#785430'][Math.floor(r() * 3)];
      ctx.fillStyle = shade;
      ctx.fillRect(x, 0, 1, s);
      if (x % 4 === 0) { ctx.fillStyle = '#4c351e'; ctx.fillRect(x, 0, 1, s); }
    }
  });
  T.planks = makeCanvas((ctx, s) => {
    speckle(ctx, s, ['#b08850', '#a37c46', '#bc9258'], 43);
    ctx.fillStyle = '#7c5e34';
    for (let y = 3; y < s; y += 4) ctx.fillRect(0, y, s, 1);
  });
  T.leaves = makeCanvas((ctx, s) => speckle(ctx, s, ['#ffffff', '#ededed', '#d9d9d9', '#c9c9c9'], 47));
  T.iron = makeCanvas((ctx, s) => speckle(ctx, s, ['#5b6168', '#50555c', '#666c74', '#454a50'], 53));
  T.gold = makeCanvas((ctx, s) => {
    speckle(ctx, s, ['#fcd34d', '#fbbf24', '#f59e0b', '#fde68a'], 59);
    ctx.fillStyle = '#fff7cc';
    ctx.fillRect(3, 3, 2, 2); ctx.fillRect(10, 9, 2, 2);
  });
  T.moon = makeCanvas((ctx, s) => {
    speckle(ctx, s, ['#e5e7eb', '#d1d5db', '#f3f4f6'], 61);
    const r = rng(67);
    for (let i = 0; i < 6; i++) {
      ctx.fillStyle = '#9ca3af';
      const x = Math.floor(r() * (s - 3)), y = Math.floor(r() * (s - 3));
      ctx.fillRect(x, y, 2 + Math.floor(r() * 2), 2);
    }
  });
  T.cloud = makeCanvas((ctx, s) => speckle(ctx, s, ['#ffffff', '#fafafa', '#f2f2f2'], 71));
  T.neonOre = makeCanvas((ctx, s) => {
    speckle(ctx, s, ['#1e1b4b', '#312e81', '#1e293b'], 73);
    const r = rng(79);
    for (let i = 0; i < 7; i++) {
      ctx.fillStyle = ['#22d3ee', '#a78bfa', '#34d399'][Math.floor(r() * 3)];
      ctx.fillRect(Math.floor(r() * (s - 2)), Math.floor(r() * (s - 2)), 2, 2);
    }
  });

  return T;
}

/** Material helpers — Lambert keeps the flat blocky look and is cheap. */
export function lambert(map, opts = {}) {
  return new THREE.MeshLambertMaterial({ map, ...opts });
}

export function emissive(map, color, intensity = 1) {
  return new THREE.MeshLambertMaterial({
    map, emissive: new THREE.Color(color), emissiveIntensity: intensity, emissiveMap: map,
  });
}

// Procedural WebAudio: wind, rail clacks, headline dings, ATH fanfare.
// No audio assets; everything is synthesized. Created lazily on first gesture.

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.clackTimer = 0;
  }

  ensure() {
    if (this.ctx) return;
    try {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.5;
      this.master.connect(this.ctx.destination);

      // wind: looped noise through a bandpass we modulate with speed
      const len = this.ctx.sampleRate * 2;
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.windSrc = this.ctx.createBufferSource();
      this.windSrc.buffer = buf;
      this.windSrc.loop = true;
      this.windFilter = this.ctx.createBiquadFilter();
      this.windFilter.type = 'bandpass';
      this.windFilter.frequency.value = 400;
      this.windFilter.Q.value = 0.6;
      this.windGain = this.ctx.createGain();
      this.windGain.gain.value = 0;
      this.windSrc.connect(this.windFilter).connect(this.windGain).connect(this.master);
      this.windSrc.start();
    } catch { this.ctx = null; }
  }

  resume() {
    this.ensure();
    if (this.ctx?.state === 'suspended') this.ctx.resume();
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.5;
    return this.muted;
  }

  /** dt-driven update. `active` = actually riding (not paused/finished/menu). */
  update(dt, speed, active) {
    if (!this.ctx) return;
    if (!active || this.muted) {
      this.windGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.15);
      return;
    }
    const k = Math.min(1, speed / 60);
    this.windGain.gain.setTargetAtTime(0.02 + k * 0.22, this.ctx.currentTime, 0.1);
    this.windFilter.frequency.setTargetAtTime(300 + k * 900, this.ctx.currentTime, 0.1);

    this.clackTimer -= dt;
    if (this.clackTimer <= 0 && speed > 2) {
      this.clackTimer = Math.max(0.075, 2.4 / speed);
      this.clack(0.05 + k * 0.1);
    }
  }

  /** Hard-stop the ambience (ride end, back to station). */
  stopAmbience() {
    if (this.ctx) this.windGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1);
  }

  clack(vol) {
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.value = 95 + Math.random() * 50;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.045);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + 0.06);
  }

  ding() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    for (const [f, dt0] of [[880, 0], [1320, 0.09]]) {
      const osc = this.ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = f;
      const g = this.ctx.createGain();
      g.gain.setValueAtTime(0.0001, t + dt0);
      g.gain.exponentialRampToValueAtTime(0.16, t + dt0 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, t + dt0 + 0.5);
      osc.connect(g).connect(this.master);
      osc.start(t + dt0);
      osc.stop(t + dt0 + 0.55);
    }
  }

  fanfare() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    [523, 659, 784, 1047].forEach((f, i) => {
      const osc = this.ctx.createOscillator();
      osc.type = 'square';
      osc.frequency.value = f;
      const g = this.ctx.createGain();
      const start = t + i * 0.11;
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(0.12, start + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, start + (i === 3 ? 0.7 : 0.16));
      osc.connect(g).connect(this.master);
      osc.start(start);
      osc.stop(start + 0.75);
    });
  }

  womp() {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(180, t);
    osc.frequency.exponentialRampToValueAtTime(55, t + 0.7);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.14, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.8);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + 0.85);
  }
}

// STOCKCOASTER — boot, station menu, ride lifecycle, input, game loop.
import * as THREE from 'three';
