    <div id="rides"></div>
    <div class="help-line">
      mouse — look around · <kbd>SPACE</kbd> pause · paused: <kbd>S</kbd> screenshot · <kbd>1</kbd>-<kbd>4</kbd> speed · <kbd>M</kbd> sound · <kbd>C</kbd> hide HUD · <kbd>R</kbd> restart · <kbd>ESC</kbd> back<br/>
      altitude = price (log scale) · read the signs — they're real headlines · the lava pit is the all-time low · space is for the trillion-dollar club
    </div>`;
  const grid = document.getElementById('rides');
  for (const entry of index) {
    const ride = state.rides.get(entry.symbol);
    const [diff, diffColor] = difficulty(ride);
    const card = document.createElement('div');
    card.className = 'ride-card panel';
    const up = ride.stats.totalReturn >= 0;
    const years = ((new Date(ride.points[ride.points.length - 1].date) - new Date(ride.points[0].date)) / 31557600000).toFixed(0);
    card.innerHTML = `
      <div class="difficulty" style="background:${diffColor}">${diff}</div>
      <h2>${esc(ride.symbol)}</h2>
      <div class="co">${esc(ride.name)} · ${years} YRS · ${ride.headlines?.length ?? 0} HEADLINES</div>
      <canvas width="264" height="74"></canvas>
      <div class="tagline">${esc(ride.tagline ?? '')}</div>
      <div class="stats">
        <span>RETURN <b class="${up ? 'up' : 'down'}">${fmtPct(ride.stats.totalReturn)}</b></span>
        <span>WORST DIP <b class="down">-${Math.round(ride.stats.maxDrawdown * 100)}%</b></span>
      </div>`;
    drawPreview(card.querySelector('canvas'), ride);
    card.addEventListener('click', () => startRide(ride.symbol));
    grid.appendChild(card);
  }
}

function drawPreview(cv, ride) {
  const ctx = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  ctx.fillStyle = '#0d1117';
  ctx.fillRect(0, 0, W, H);
  const pts = ride.points;
  let lmin = Infinity, lmax = -Infinity;
  for (const p of pts) {
    const l = Math.log(p.close);
    if (l < lmin) lmin = l;
    if (l > lmax) lmax = l;
  }
  const span = Math.max(1e-9, lmax - lmin);
  ctx.strokeStyle = ride.stats.totalReturn >= 0 ? '#4ade80' : '#f87171';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = 0; i < pts.length; i++) {
    const x = 3 + (i / (pts.length - 1)) * (W - 6);
    const y = H - 4 - ((Math.log(pts[i].close) - lmin) / span) * (H - 8);
    i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
  }
  ctx.stroke();
}

// ---------------------------------------------------------------- ride lifecycle
async function startRide(symbol) {
  const ride = state.rides.get(symbol);
  if (!ride) return;
  document.getElementById('loading').style.display = 'flex';
  // let the loading overlay actually paint before the synchronous scene build
  await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));

  disposeRide();

  const scene = new THREE.Scene();
  const theme = getTheme(ride.theme);
  const track = buildTrackData(ride, theme);

  const groups = [
    buildTrackMeshes(track, T, theme),
    buildTerrain(track, T, theme),
    buildBillboards(track, T, theme, ride),
    buildStations(track, T, theme, ride),
  ];
  for (const g of groups) scene.add(g);

  state.scene = scene;
  state.ride = ride;
  state.track = track;
  state.groups = groups;
  state.sky = new Sky(scene, T, track);
  state.cart = new Cart(scene, track, T, camera);
  state.effects = new Effects(scene);
  state.mode = 'riding';
  state.paused = false;
  state.seenHeadlines = new Set();
  state.seenConfetti = new Set();
  state.lastDrawdownDeep = false;
  state.launchFxAcc = 0;

  document.getElementById('menu').style.display = 'none';
  document.getElementById('loading').style.display = 'none';
  hud.show(ride);
  hud.hideSummary();
  showLockHint(true);
}

const SHARED_TEXTURES = new Set(Object.values(T));

function disposeRide() {
  if (!state.scene) return;
  // dispose while everything is still in the scene graph, then detach
  state.scene.traverse(o => {
    if (o.isInstancedMesh) o.dispose(); // frees instanceMatrix/instanceColor GPU buffers
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      for (const m of Array.isArray(o.material) ? o.material : [o.material]) {
        if (m.map && !SHARED_TEXTURES.has(m.map)) m.map.dispose(); // per-ride sign canvases
        m.dispose();
      }
    }
  });
  state.sky?.dispose();
  state.cart?.dispose();
  state.effects?.dispose();
  state.scene = null;
  state.cart = null;
  state.sky = null;
  state.effects = null;
  state.track = null;
}

function exitToMenu() {
  document.exitPointerLock?.();
  audio.stopAmbience();
  state.mode = 'menu';
  disposeRide();
  hud.hide();
  hud.hideSummary();
  showLockHint(false);
  document.getElementById('menu').style.display = 'block';
}

function finishRide() {
  document.exitPointerLock?.();
  audio.stopAmbience();
  showLockHint(false);
  state.paused = false;
  hud.showSummary(state.ride);
  if (state.ride.stats.totalReturn >= 0) audio.fanfare();
  else audio.womp();
}

// ---------------------------------------------------------------- input
const lockHint = document.getElementById('lock-hint');
function showLockHint(v) {
  lockHint.style.display = v ? 'flex' : 'none';
  if (v) state.paused = true;
}

let hadLock = false;     // pointer lock was successfully acquired at least once
let dragLook = false;    // fallback when pointer lock is unavailable/denied
let dragging = false;

lockHint.addEventListener('click', () => {
  audio.resume();
  try {
    const p = canvas.requestPointerLock?.();
    p?.catch?.(() => { dragLook = true; });
    if (!canvas.requestPointerLock) dragLook = true;
  } catch { dragLook = true; }
  showLockHint(false);
  state.paused = false;
});

document.addEventListener('pointerlockchange', () => {
  if (document.pointerLockElement === canvas) {
    hadLock = true;
    return;
  }
  // Only treat lock loss as "pause" if we actually had the lock (ESC pressed).
  // If lock never engaged (headless/denied), keep riding with drag-look.
  if (hadLock && state.mode === 'riding' && !state.cart?.finished) {
    showLockHint(true);
  } else if (state.mode === 'riding') {
    dragLook = true;
  }
  hadLock = false;
});

document.addEventListener('mousemove', e => {
  if (!state.cart) return;
  if (document.pointerLockElement === canvas) {
    state.cart.onMouse(e.movementX, e.movementY);
  } else if (dragLook && dragging) {
    state.cart.onMouse(e.movementX, e.movementY);
  }
});
canvas.addEventListener('mousedown', () => { dragging = true; });
document.addEventListener('mouseup', () => { dragging = false; });

// click the HUD minimap to jump anywhere in the ride
hud.onSeek = index => {
  if (state.mode !== 'riding' || !state.track || !state.cart) return;
  const track = state.track;
  const i = Math.min(index, track.uAtPoint.length - 1);
  state.cart.s = Math.max(2, Math.min(track.length - 2, track.uAtPoint[i] * track.length));
  state.cart.v = 12;
  state.cart.finished = false;
  hud.hideSummary();
  // everything before the target is "already seen" (no toast flood);
  // everything after re-arms so a replayed section celebrates again
  state.seenHeadlines = new Set(
    (state.ride.headlines ?? [])
      .filter(h => h.pointIndex < i - 1)
      .map(h => h.pointIndex + ':' + h.title),
  );
  state.seenConfetti = new Set();
  for (let k = 0; k < i; k++) state.seenConfetti.add(k);
  // clicking the map while the pause overlay is up counts as "ride"
  if (lockHint.style.display === 'flex') {
    audio.resume();
    showLockHint(false);
    state.paused = false;
  }
};

function speedLevelFromKey(e) {
  // Real browsers/keyboards can report either physical codes, typed chars,
  // numpad codes, or shifted symbols. Accept all of them for speed control.
  const codeMatch = /^(?:Digit|Numpad)([1-4])$/.exec(e.code || '');
  if (codeMatch) return Number(codeMatch[1]);
  const key = String(e.key || '');
  if (/^[1-4]$/.test(key)) return Number(key);
  return ({ '!': 1, '@': 2, '#': 3, '$': 4 })[key] ?? 0;
}


function downloadScreenshot() {
  if (!canvas || state.mode !== 'riding') return;
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const symbol = state.ride?.symbol ?? 'STOCKCOASTER';
  canvas.toBlob(blob => {
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `stockcoaster-${symbol}-${stamp}.png`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
  }, 'image/png');
}

function onRideKeydown(e) {
  if (state.mode !== 'riding') return;

  const speedLevel = speedLevelFromKey(e);
  if (speedLevel) {
    e.preventDefault();
    e.stopPropagation();
    state.cart.setSpeedLevel(speedLevel);
    hud.flashSpeed(speedLevel);
    return;
  }

  switch (e.code || e.key) {
    case 'Space':
    case ' ':
      e.preventDefault();
      e.stopImmediatePropagation();
      if (lockHint.style.display !== 'flex') state.paused = !state.paused;
      break;
    case 'KeyS':
    case 's':
    case 'S':
      if (state.paused && lockHint.style.display !== 'flex') {
        e.preventDefault();
        e.stopImmediatePropagation();
        downloadScreenshot();
      }
      break;
    case 'KeyM':
    case 'm':
    case 'M': audio.toggleMute(); break;
    case 'KeyC':
    case 'c':
    case 'C': hud.toggleCinematic(); break;
    case 'KeyR':
    case 'r':
    case 'R':
      state.cart.restart();
      state.seenHeadlines.clear();
      state.seenConfetti.clear();
      hud.hideSummary();
      if (document.pointerLockElement !== canvas) showLockHint(true);
      break;
    case 'Escape':
      // browser releases pointer lock on its own; second ESC (overlay visible) exits
      if (lockHint.style.display === 'flex' || state.cart?.finished) exitToMenu();
      break;
  }
}

window.addEventListener('keydown', onRideKeydown, { capture: true });

document.getElementById('btn-again').addEventListener('click', () => {
  state.cart.restart();
  state.seenHeadlines.clear();
  state.seenConfetti.clear();
  hud.hideSummary();
  showLockHint(true);
});
document.getElementById('btn-station').addEventListener('click', exitToMenu);

window.addEventListener('resize', () => {
  renderer.setSize(window.innerWidth, window.innerHeight);
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
});

// ---------------------------------------------------------------- ride events
const _back = new THREE.Vector3();
function rideEvents(dt) {
  const { cart, ride, track } = state;
  const idx = cart.pointIndex;
  const meta = track.meta[idx];

  // headline toasts + ding
  for (const h of ride.headlines ?? []) {
    if (h.pointIndex <= idx && !state.seenHeadlines.has(h.pointIndex + ':' + h.title)) {
      if (idx - h.pointIndex <= 2) {
        hud.toast(h);
        audio.ding();
      }
      state.seenHeadlines.add(h.pointIndex + ':' + h.title);
    }
  }

  // confetti + fanfare at meaningful new all-time highs
  if (meta.athParty && !state.seenConfetti.has(idx)) {
    state.seenConfetti.add(idx);
    state.effects.confetti(cart.frame.pos);
    hud.flashATH();
    audio.fanfare();
  }

  // womp when first diving deep underwater (drawdown > 50%)
  const deep = meta.drawdown > 0.5;
  if (deep && !state.lastDrawdownDeep) audio.womp();
  state.lastDrawdownDeep = deep;

  // rocket exhaust on monster green candles (meme magic)
  if (meta.gain > 0.35 && !cart.paused) {
    _back.copy(cart.frame.tan).negate();
    state.effects.rocketBoost(cart.frame.pos, _back);
  }

  // SPCX launch-day spectacle: keep firing rockets into the sky while the IPO tape runs.
  if (ride.theme === 'launch') {
    state.launchFxAcc += dt;
    const fastMove = meta.gain > 0.012 || meta.drawdown > 0.06;
    if (state.launchFxAcc > (fastMove ? 1.15 : 2.35)) {
      state.launchFxAcc = 0;
      state.effects.launchShow(cart.frame.pos, cart.frame.tan);
      if (Math.random() < 0.35) state.effects.launchShow(cart.frame.pos, cart.frame.tan);
    }
  }
}

// ---------------------------------------------------------------- loop
const clock = new THREE.Clock();
function loop() {
  requestAnimationFrame(loop);
  const dt = Math.min(clock.getDelta(), 0.05);
  state.time += dt;

  if (state.mode !== 'riding' || !state.scene) return;

  const wasFinished = state.cart.finished;
  state.cart.paused = state.paused;
  state.cart.update(dt);
  if (state.cart.finished && !wasFinished) finishRide();

  const camY = camera.position.y;
  const atm = sampleAtmosphere(camY);
  state.sky.update(dt, camera.position, state.time);

  const idx = state.cart.pointIndex;
  const meta = state.track.meta[idx];
  if (!state.paused) {
    state.effects.ambient(dt, camera.position, camY, meta.drawdown, atm.spaceness);
    rideEvents(dt);
  }
  state.effects.update(dt);

  hud.update(state.ride, idx, atm, state.cart.v, state.paused, dt);
  audio.update(dt, state.cart.v, !state.paused && !state.cart.finished);

  renderer.render(state.scene, camera);
}

function esc(s) {
  return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}

boot();
loop();

// News billboards, milestone arches, year markers and the start/end stations.
// Sign faces are canvas textures drawn at low res and upscaled -> pixel look.
import * as THREE from 'three';
import { lambert } from './textures.js';
import { groundHeight } from './terrain.js';

const SENTIMENT = {
  pos: { frame: '#15803d', accent: '#4ade80', tag: 'GOOD NEWS' },
  neg: { frame: '#b91c1c', accent: '#f87171', tag: 'BAD NEWS' },
  neutral: { frame: '#52525b', accent: '#d4d4d8', tag: 'NEWS' },
};

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

export function fmtDate(iso) {
  const [y, m] = iso.split('-').map(Number);
  return `${MONTHS[(m - 1 + 12) % 12]} ${y}`;
}

function wrap(ctx, text, maxW) {
  const words = String(text).split(/\s+/);
  const lines = [];
  let line = '';
  for (const w of words) {
    const probe = line ? line + ' ' + w : w;
    if (ctx.measureText(probe).width > maxW && line) {
      lines.push(line);
      line = w;
    } else line = probe;
  }
  if (line) lines.push(line);
  return lines;
}

function panelTexture({ title, dateLabel, sentiment = 'neutral', big = false }) {
  const s = SENTIMENT[sentiment] ?? SENTIMENT.neutral;
  const W = 128;

  // Measure first, then grow the sign canvas vertically. Long IPO headlines used
  // to overflow a fixed 80px texture; now every wrapped line gets real pixels.
  const measure = document.createElement('canvas');
  measure.width = W; measure.height = 1;
  const mctx = measure.getContext('2d');
  const fontPx = big && String(title).length < 64 ? 10 : 9;
  const lineH = fontPx + 3;
  mctx.font = `bold ${fontPx}px monospace`;
  const lines = wrap(mctx, title, W - 18);
  const top = dateLabel ? 26 : 14;
  const bottom = 8;
  const H = Math.max(80, top + lines.length * lineH + bottom);

  const lo = document.createElement('canvas');
  lo.width = W; lo.height = H;
  const ctx = lo.getContext('2d');

  ctx.fillStyle = '#cdb27c';
  ctx.fillRect(0, 0, W, H);
  for (let y = 0; y < H; y += 7) { ctx.fillStyle = 'rgba(124,94,52,.28)'; ctx.fillRect(0, y, W, 1); }
  ctx.fillStyle = s.frame;
  ctx.fillRect(0, 0, W, 4); ctx.fillRect(0, H - 4, W, 4);
  ctx.fillRect(0, 0, 4, H); ctx.fillRect(W - 4, 0, 4, H);

  ctx.fillStyle = '#3b2a16';
  ctx.font = 'bold 8px monospace';
  ctx.textAlign = 'center';
  if (dateLabel) {
    ctx.fillStyle = s.frame;
    ctx.fillRect(W / 2 - 30, 7, 60, 11);
    ctx.fillStyle = '#fff';
    ctx.fillText(dateLabel, W / 2, 16);
  }
  ctx.fillStyle = '#2b1d0e';
  ctx.font = `bold ${fontPx}px monospace`;
  let y = top + fontPx;
  for (const l of lines) { ctx.fillText(l, W / 2, y); y += lineH; }

  // upscale 4x with no smoothing -> chunky pixels
  const hi = document.createElement('canvas');
  hi.width = W * 4; hi.height = H * 4;
  const hctx = hi.getContext('2d');
  hctx.imageSmoothingEnabled = false;
  hctx.drawImage(lo, 0, 0, hi.width, hi.height);

  const tex = new THREE.CanvasTexture(hi);
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  tex.userData.aspect = W / H;
  tex.userData.lineCount = lines.length;
  return tex;
}

function makeSign(tex, w, h, T, frameColor = 0x6b4a2a) {
  const g = new THREE.Group();
  const panel = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, 0.22),
    [
      lambert(T.planks), lambert(T.planks), lambert(T.planks), lambert(T.planks),
      new THREE.MeshBasicMaterial({ map: tex }), // front face (+z): unlit so it's readable everywhere
      lambert(T.planks),
    ],
  );
  g.add(panel);
  const postMat = new THREE.MeshLambertMaterial({ color: frameColor });
  // posts run from panel center down to ~3.6 below the panel, hidden behind it
  const postLen = h / 2 + 3.6;
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(0.38, postLen, 0.38), postMat);
    post.position.set(side * (w / 2 - 0.35), -(h / 4 + 1.8), -0.16);
    g.add(post);
  }
  g.userData.panelWidth = w;
  g.userData.panelHeight = h;
  return g;
}

export function buildBillboards(track, T, theme, ride) {
  const group = new THREE.Group();
  const n = track.controlPoints.length;
  const lookTarget = new THREE.Vector3();

  const place = (sign, pointIndex, side, dist, lift) => {
    const i = THREE.MathUtils.clamp(pointIndex, 0, n - 1);
    const cp = track.controlPoints[i];
    const prev = track.controlPoints[Math.max(0, i - 3)];
    const tangent = new THREE.Vector3().subVectors(cp, prev);
    tangent.y = 0;
    if (tangent.lengthSq() < 1e-6) tangent.set(1, 0, 0);
    tangent.normalize();
    const lat = new THREE.Vector3(-tangent.z, 0, tangent.x);
    sign.position.copy(cp).addScaledVector(lat, side * dist);
    const surfaceY = groundHeight(sign.position.x, sign.position.z, ride.symbol);
    const panelH = sign.userData.panelHeight ?? 4.6;
    // Low launch-day tracks can sit inside a trench; signs should read above the nearby terrain, not drown in it.
    sign.position.y = Math.max(cp.y + lift, surfaceY + panelH * 0.5 + 4.1);
    // face a spot on the track ~4 points back, where the rider reads it from
    const back = track.controlPoints[Math.max(0, i - 4)];
    lookTarget.set(back.x, sign.position.y, back.z);
    sign.lookAt(lookTarget);
    group.add(sign);
  };

  // --- headline signs, alternating sides; same-point signs fan out so they
  // never overlap (opposite side first, then further out and higher)
  let side = 1;
  const stacked = new Map(); // pointIndex -> how many signs already placed there
  for (const h of ride.headlines ?? []) {
    if (h.pointIndex == null) continue;
    const count = stacked.get(h.pointIndex) ?? 0;
    stacked.set(h.pointIndex, count + 1);
    const imp = h.importance ?? 1;
    const launchOpening = theme.launchDay && h.pointIndex < 12;
    const baseScale = imp === 3 ? 1.45 : imp === 2 ? 1.18 : 1.0;
    // The first SPCX minutes are dense; keep opening signs readable without giant panels filling the camera.
    const scale = launchOpening ? Math.min(baseScale, 0.92) : baseScale;
    const tex = panelTexture({
      title: h.title,
      dateLabel: fmtDate(h.date),
      sentiment: h.sentiment,
      big: imp >= 3,
    });
    const signW = 7.4 * scale;
    const signH = signW / (tex.userData.aspect || 1.6);
    const sign = makeSign(tex, signW, signH, T, theme.signFrame);
    const s = count % 2 === 0 ? side : -side;
    const tier = launchOpening ? 0 : Math.floor(count / 2);
    const visualIndex = launchOpening ? Math.min(n - 1, h.pointIndex + 5) : h.pointIndex;
    const dist = launchOpening ? 13.5 + imp * 0.35 : 9.5 + imp * 0.8 + tier * 7;
    const lift = launchOpening ? 9.5 + scale + count * 0.55 : 2.4 + scale + tier * 3.4;
    place(sign, visualIndex, s, dist, lift);
    if (count === 0) side *= -1;
  }

  // --- milestone arches spanning the track
  for (const ms of ride.milestones ?? []) {
    if (ms.pointIndex == null) continue;
    const i = ms.pointIndex;
    const cp = track.controlPoints[i];
    const next = track.controlPoints[Math.min(n - 1, i + 2)];
    const dir = new THREE.Vector3().subVectors(next, cp);
    dir.y = 0;
    if (dir.lengthSq() < 1e-6) dir.set(1, 0, 0);
    dir.normalize();
    const lat = new THREE.Vector3(-dir.z, 0, dir.x);

    const arch = new THREE.Group();
    const gold = new THREE.MeshLambertMaterial({
      color: 0xfcd34d, emissive: 0x8a6508, emissiveIntensity: 0.55,
    });
    for (const s of [-1, 1]) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(0.7, 9.2, 0.7), gold);
      post.position.copy(lat).multiplyScalar(s * 5.4);
      post.position.y = 1.8;
      arch.add(post);
    }
    const lo = document.createElement('canvas'); // banner texture
    lo.width = 128; lo.height = 24;
    const ctx = lo.getContext('2d');
    ctx.fillStyle = '#1c1917'; ctx.fillRect(0, 0, 128, 24);
    ctx.fillStyle = '#fcd34d'; ctx.fillRect(0, 0, 128, 2); ctx.fillRect(0, 22, 128, 2);
    ctx.font = 'bold 9px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#fde68a';
    const label = String(ms.label).slice(0, 26);
    ctx.fillText(label, 64, 16);
    const hi = document.createElement('canvas');
    hi.width = 512; hi.height = 96;
    const hctx = hi.getContext('2d');
    hctx.imageSmoothingEnabled = false;
    hctx.drawImage(lo, 0, 0, 512, 96);
    const btex = new THREE.CanvasTexture(hi);
    btex.magFilter = THREE.NearestFilter;
    btex.colorSpace = THREE.SRGBColorSpace;
    const banner = new THREE.Mesh(
      new THREE.BoxGeometry(11.5, 2.2, 0.3),
      [gold, gold, gold, gold,
        new THREE.MeshBasicMaterial({ map: btex }),
        new THREE.MeshBasicMaterial({ map: btex })],
    );
    banner.position.y = 5.5;
    arch.add(banner);

    const archGround = groundHeight(cp.x, cp.z, ride.symbol);
    arch.position.set(cp.x, Math.max(cp.y, archGround + 1.4), cp.z);
    const yaw = Math.atan2(dir.x, dir.z);
    arch.rotation.y = yaw;
    group.add(arch);
  }

  // --- year marker posts
  const span = (new Date(ride.points[n - 1].date).getTime() - new Date(ride.points[0].date).getTime()) / 31557600000;
  const step = span > 24 ? 5 : 1;
  let lastYear = null;
  for (let i = 0; i < n; i++) {
    const year = Number(ride.points[i].date.slice(0, 4));
    if (year !== lastYear) {
      lastYear = year;
      if (i === 0 || year % step !== 0) continue;
      const tex = panelTexture({ title: String(year), sentiment: 'neutral', big: true });
      const sign = makeSign(tex, 3.0, 1.9, T, theme.signFrame);
      place(sign, i, (year % 2) * 2 - 1, 6.5, 1.1);
    }
  }

  return group;
}

/** Wooden platform + big title sign at the start, buffer stop at the end. */
export function buildStations(track, T, theme, ride) {
  const group = new THREE.Group();
  const n = track.controlPoints.length;

  const mkPlatform = (cp, tangent) => {
    const g = new THREE.Group();
    const plat = new THREE.Mesh(new THREE.BoxGeometry(16, 1.1, 12), lambert(T.planks));
    plat.position.set(0, -1.35, 0);
    g.add(plat);
    const postMat = lambert(T.log);
    for (const [px, pz] of [[-7, -5], [7, -5], [-7, 5], [7, 5]]) {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(1, 14, 1), postMat);
      leg.position.set(px, -8, pz);
      g.add(leg);
      const torch = new THREE.Mesh(
        new THREE.BoxGeometry(0.4, 0.9, 0.4),
        new THREE.MeshLambertMaterial({ color: 0xffc14d, emissive: 0xff9d00, emissiveIntensity: 1.4 }),
      );
      torch.position.set(px, 0.6, pz);
      g.add(torch);
    }
    g.position.set(cp.x, cp.y, cp.z);
    g.rotation.y = Math.atan2(tangent.x, tangent.z) - Math.PI / 2;
    return g;
  };

  const t0 = new THREE.Vector3().subVectors(track.controlPoints[1], track.controlPoints[0]).setY(0).normalize();
  const start = mkPlatform(track.controlPoints[0], t0);
  const titleTex = panelTexture({
    title: `${ride.symbol} — ${ride.name}`,
    dateLabel: 'NOW BOARDING',
    sentiment: 'pos',
    big: true,
  });
  const titleSign = makeSign(titleTex, 9, 5.4, T, theme.signFrame);
  titleSign.position.set(0, 4.6, -5.4);
  titleSign.rotation.y = Math.PI;
  start.add(titleSign);
  group.add(start);

  const tEnd = new THREE.Vector3().subVectors(
    track.controlPoints[n - 1], track.controlPoints[n - 2],
  ).setY(0).normalize();
  const end = mkPlatform(track.controlPoints[n - 1], tEnd);
  group.add(end);

  // buffer stop
  const stop = new THREE.Mesh(new THREE.BoxGeometry(3.4, 2.2, 1.2), lambert(T.iron));
  const endCp = track.controlPoints[n - 1];
  stop.position.copy(endCp).addScaledVector(tEnd, 5);
  stop.position.y = endCp.y + 0.8;
  group.add(stop);

  return group;
}

// The minecart, the camera rig, and the ride physics.
// Speed is semi-physical: gravity along the track plus a "chain motor" that
// pulls speed back toward cruise so climbs never stall and drops still rip.
import * as THREE from 'three';
import { frameAt, makeFrame, pointIndexAtU } from './track.js';
import { lambert } from './textures.js';

const CRUISE = 17;
const V_MIN = 7;
const V_MAX = 64;
const SPEEDS = { 1: 0.6, 2: 1.0, 3: 1.7, 4: 2.6 };

export class Cart {
  constructor(scene, track, T, camera) {
    this.track = track;
    this.camera = camera;
    this.scene = scene;

    this.s = 2;             // arc length along track
    this.v = 10;
    this.speedMult = 1;
    this.speedLevel = 2;
    this.paused = false;
    this.finished = false;
    this.frame = makeFrame();
    this.yaw = 0;
    this.pitch = 0;
    this.smoothTan = new THREE.Vector3(1, 0, 0);
    this.smoothUp = new THREE.Vector3(0, 1, 0);
    this.shake = 0;

    // --- minecart mesh
    const g = new THREE.Group();
    const ironMat = lambert(T.iron);
    const body = new THREE.Mesh(new THREE.BoxGeometry(2.4, 1.0, 3.2), ironMat);
    body.position.y = 0.62;
    g.add(body);
    const inner = new THREE.Mesh(
      new THREE.BoxGeometry(1.9, 0.5, 2.7),
      new THREE.MeshLambertMaterial({ color: 0x7a3030 }),
    );
    inner.position.y = 1.0;
    g.add(inner);
    for (const [wx, wz] of [[-1.1, -1.05], [1.1, -1.05], [-1.1, 1.05], [1.1, 1.05]]) {
      const wheel = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.62, 0.62), ironMat);
      wheel.position.set(wx, 0.18, wz);
      g.add(wheel);
    }
    this.mesh = g;
    scene.add(g);

    this.tmpQ = new THREE.Quaternion();
    this.tmpM = new THREE.Matrix4();
    this.camTarget = new THREE.Vector3();
    this.lookDir = new THREE.Vector3();
  }

  onMouse(dx, dy) {
    this.yaw -= dx * 0.0024;
    this.pitch -= dy * 0.0022;
    this.yaw = THREE.MathUtils.clamp(this.yaw, -2.7, 2.7);
    this.pitch = THREE.MathUtils.clamp(this.pitch, -1.2, 1.25);
  }

  setSpeedLevel(level) {
    const mult = SPEEDS[level] ?? 1;
    const oldTarget = CRUISE * this.speedMult;
    const newTarget = CRUISE * mult;
    this.speedLevel = level;
    this.speedMult = mult;

    // Make key presses feel like a control, not a suggestion to the physics loop.
    // Gravity can still spice the ride, but 1/2/3/4 now immediately lands in a visibly different speed band.
    if (newTarget > oldTarget) this.v = Math.max(this.v, newTarget * 0.92);
    else this.v = Math.min(this.v, newTarget * 1.05);
    this.v = THREE.MathUtils.clamp(this.v, V_MIN * mult, V_MAX * Math.max(1, mult));
  }

  update(dt) {
    if (this.finished) return;
    const u = THREE.MathUtils.clamp(this.s / this.track.length, 0, 1);
    frameAt(this.track, u, this.frame);

    if (!this.paused) {
      const slope = this.frame.tan.y;
      // gravity along track + motor toward cruise speed
      this.v += (-22 * slope) * dt;
      this.v += (CRUISE * this.speedMult - this.v) * 1.25 * dt;
      this.v = THREE.MathUtils.clamp(this.v, V_MIN * this.speedMult, V_MAX * Math.max(1, this.speedMult));
      this.s += this.v * dt;
      if (this.s >= this.track.length - 1.2) {
        this.s = this.track.length - 1.2;
        this.finished = true;
      }
    }

    // orientation smoothing keeps the camera from jittering on noisy frames
    const k = 1 - Math.exp(-10 * dt);
    this.smoothTan.lerp(this.frame.tan, k).normalize();
    this.smoothUp.lerp(this.frame.up, k).normalize();

    // place cart
    const lat = new THREE.Vector3().crossVectors(this.smoothTan, this.smoothUp).negate().normalize();
    this.tmpM.makeBasis(lat, this.smoothUp, this.smoothTan);
    this.tmpQ.setFromRotationMatrix(this.tmpM);
    this.mesh.position.copy(this.frame.pos).addScaledVector(this.frame.up, 0.25);
    this.mesh.quaternion.copy(this.tmpQ);

    // camera: seat position + free look (yaw/pitch relative to travel direction)
    this.shake = Math.min(1, this.v / V_MAX);
    const t = performance.now() * 0.001;
    const shakeAmp = 0.05 * this.shake;
    this.camTarget.copy(this.frame.pos)
      .addScaledVector(this.smoothUp, 2.1)
      .addScaledVector(this.smoothTan, 0.7)
      .addScaledVector(lat, Math.sin(t * 23) * shakeAmp)
      .addScaledVector(this.smoothUp, Math.sin(t * 31) * shakeAmp);
    this.camera.position.copy(this.camTarget);

    this.lookDir.copy(this.smoothTan)
      .applyAxisAngle(this.smoothUp, this.yaw);
    const pitchAxis = new THREE.Vector3().crossVectors(this.smoothUp, this.lookDir).normalize();
    this.lookDir.applyAxisAngle(pitchAxis, -this.pitch);
    this.camTarget.addScaledVector(this.lookDir, 10);
    this.camera.up.copy(this.smoothUp);
    this.camera.lookAt(this.camTarget);

    // dynamic FOV: subtle speed rush
    const targetFov = 72 + 16 * Math.pow(this.v / V_MAX, 1.6);
    this.camera.fov += (targetFov - this.camera.fov) * Math.min(1, 6 * dt);
    this.camera.updateProjectionMatrix();
  }

  get u() { return THREE.MathUtils.clamp(this.s / this.track.length, 0, 1); }
  get pointIndex() { return pointIndexAtU(this.track, this.u); }

  restart() {
    this.s = 2;
    this.v = 10;
    this.setSpeedLevel(2);
    this.finished = false;
    this.yaw = 0;
    this.pitch = 0;
  }

  dispose() {
    this.scene.remove(this.mesh);
  }
}

