// Voxel terrain ribbon under the track: instanced columns with grass caps,
// trees/flowers, a lava trench carved wherever the price scrapes its all-time
// low, and a gold patch under the all-time-high peak.
import * as THREE from 'three';
import { lambert, emissive } from './textures.js';

const COL = 4;           // column footprint (world units)
const HALF_WIDTH = 44;   // terrain extends this far on each side of the path

function hashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function hash2(ix, iz, seed) {
  let h = seed ^ Math.imul(ix, 374761393) ^ Math.imul(iz, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

function smooth(t) { return t * t * (3 - 2 * t); }

function noise2(x, z, seed) {
  const ix = Math.floor(x), iz = Math.floor(z);
  const fx = x - ix, fz = z - iz;
  const a = hash2(ix, iz, seed), b = hash2(ix + 1, iz, seed);
  const c = hash2(ix, iz + 1, seed), d = hash2(ix + 1, iz + 1, seed);
  const u = smooth(fx), v = smooth(fz);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

/** Deterministic terrain height. Used by track supports and terrain alike. */
export function groundHeight(x, z, symbol) {
  const seed = hashStr(symbol || 'STONK');
  const n1 = noise2(x * 0.022 + 31.7, z * 0.022 + 11.3, seed);
  const n2 = noise2(x * 0.006 + 7.1, z * 0.006 + 3.9, seed ^ 0x9e3779b9);
  return 15 + n1 * 5 + n2 * 8;
}

export function buildTerrain(track, T, theme) {
  const group = new THREE.Group();
  const symbol = track.ride.symbol;
  const seed = hashStr(symbol);
  const n = track.controlPoints.length;
  const box = new THREE.BoxGeometry(1, 1, 1);

  const xMin = -24, xMax = (n - 1) * 6 + 24;
  const cols = [];
  const lava = [];
  const decor = { tree: [], dead: [], flower: [], gold: [], ore: [] };

  const peakX = track.ride.stats.maxIndex * 6;

  for (let x = xMin; x <= xMax; x += COL) {
    // nearest data point for trench/meander lookup
    const pi = THREE.MathUtils.clamp(Math.round(x / 6), 0, n - 1);
    const cp = track.controlPoints[pi];
    const trench = track.meta[pi].trench;
    for (let dz = -HALF_WIDTH; dz <= HALF_WIDTH; dz += COL) {
      const z = Math.round((cp.z + dz) / COL) * COL;
      const gh = groundHeight(x, z, symbol);
      const r = hash2(x * 13, z * 7, seed ^ 0x51ed);

      if (trench && Math.abs(z - cp.z) < 10) {
        // carved trench: low scorched floor, lava pools
        const floorY = 7.5 + r * 1.2;
        cols.push({ x, z, h: floorY, kind: 'trench' });
        if (r > 0.72) lava.push({ x, z, y: floorY + 0.1 });
        continue;
      }

      cols.push({ x, z, h: gh, kind: 'grass', r });

      const nearTrack = Math.abs(z - cp.z) < 11;
      if (!nearTrack) {
        if (Math.abs(x - peakX) < 10 && r > 0.45) {
          decor.gold.push({ x, z, y: gh });
        } else if (r > 0.962) {
          (theme.deadTrees ? decor.dead : decor.tree).push({ x, z, y: gh, s: 0.8 + r * 0.5 });
        } else if (r > 0.91) {
          decor.flower.push({ x, z, y: gh, c: theme.flowers[Math.floor(r * 997) % theme.flowers.length] });
        } else if (theme.neonOre && r < 0.025) {
          decor.ore.push({ x, z, y: gh });
        }
      }
    }
  }

  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const v = new THREE.Vector3();
  const sc = new THREE.Vector3();
  const colC = new THREE.Color();

  // --- column bodies (dirt sides, stretched from y=0 to surface)
  const bodies = new THREE.InstancedMesh(box, lambert(T.dirt), cols.length);
  // --- caps (tintable near-white grass texture)
  const caps = new THREE.InstancedMesh(box, lambert(T.grassTop), cols.length);
  const grassA = new THREE.Color(theme.grass), grassB = new THREE.Color(theme.grassAlt);
  const trenchC = new THREE.Color(0x6b3b34);

  for (let i = 0; i < cols.length; i++) {
    const c = cols[i];
    m.compose(v.set(c.x, c.h / 2, c.z), q, sc.set(COL, c.h, COL));
    bodies.setMatrixAt(i, m);
    m.compose(v.set(c.x, c.h + 0.35, c.z), q, sc.set(COL, 0.7, COL));
    caps.setMatrixAt(i, m);
    if (c.kind === 'trench') {
      caps.setColorAt(i, trenchC);
      bodies.setColorAt(i, colC.set(0x6b4540));
    } else {
      const t = hash2(c.x * 3, c.z * 5, seed ^ 0xabc1) * 0.9;
      caps.setColorAt(i, colC.copy(grassA).lerp(grassB, t));
      bodies.setColorAt(i, colC.set(0xffffff));
    }
  }
  group.add(bodies, caps);

  // --- lava pools
  if (lava.length) {
    const lavaMesh = new THREE.InstancedMesh(box, emissive(T.lava, 0xff6a00, 1.0), lava.length);
    lava.forEach((p, i) => {
      m.compose(v.set(p.x, p.y, p.z), q, sc.set(COL, 0.5, COL));
      lavaMesh.setMatrixAt(i, m);
    });
    group.add(lavaMesh);
  }

  // --- trees: trunks + leaf blobs
  if (decor.tree.length) {
    const trunks = new THREE.InstancedMesh(box, lambert(T.log), decor.tree.length);
    const leaves = new THREE.InstancedMesh(box, lambert(T.leaves), decor.tree.length * 2);
    const leafC = new THREE.Color(theme.foliage);
    decor.tree.forEach((t, i) => {
      m.compose(v.set(t.x, t.y + 1.9 * t.s, t.z), q, sc.set(1.1, 3.8 * t.s, 1.1));
      trunks.setMatrixAt(i, m);
      m.compose(v.set(t.x, t.y + 4.4 * t.s, t.z), q, sc.set(4.4 * t.s, 2.6 * t.s, 4.4 * t.s));
      leaves.setMatrixAt(i * 2, m);
      m.compose(v.set(t.x, t.y + 6.2 * t.s, t.z), q, sc.set(2.4 * t.s, 1.6 * t.s, 2.4 * t.s));
      leaves.setMatrixAt(i * 2 + 1, m);
      leaves.setColorAt(i * 2, leafC);
      leaves.setColorAt(i * 2 + 1, leafC);
    });
    group.add(trunks, leaves);
  }

  // --- dead trees (rust theme): bare trunks with a stub branch
  if (decor.dead.length) {
    const trunks = new THREE.InstancedMesh(box, lambert(T.log), decor.dead.length * 2);
    decor.dead.forEach((t, i) => {
      m.compose(v.set(t.x, t.y + 2.2 * t.s, t.z), q, sc.set(0.9, 4.4 * t.s, 0.9));
      trunks.setMatrixAt(i * 2, m);
      m.compose(v.set(t.x + 0.9, t.y + 3.4 * t.s, t.z), q, sc.set(1.8, 0.6, 0.6));
      trunks.setMatrixAt(i * 2 + 1, m);
    });
    const gray = new THREE.Color(0x7a7a72);
    for (let i = 0; i < decor.dead.length * 2; i++) trunks.setColorAt(i, gray);
    group.add(trunks);
  }

  // --- flowers
  if (decor.flower.length) {
    const flowers = new THREE.InstancedMesh(box, new THREE.MeshLambertMaterial({ color: 0xffffff }), decor.flower.length);
    decor.flower.forEach((f, i) => {
      m.compose(v.set(f.x, f.y + 1.0, f.z), q, sc.set(0.45, 0.8, 0.45));
      flowers.setMatrixAt(i, m);
      flowers.setColorAt(i, colC.set(f.c));
    });
    group.add(flowers);
  }

  // --- gold patch under the all-time-high peak
  if (decor.gold.length) {
    const gold = new THREE.InstancedMesh(box, emissive(T.gold, 0xb8860b, 0.35), decor.gold.length);
    decor.gold.forEach((g, i) => {
      m.compose(v.set(g.x, g.y + 0.45, g.z), q, sc.set(COL, 0.9, COL));
      gold.setMatrixAt(i, m);
    });
    group.add(gold);
  }

  // --- glowing crypto ore
  if (decor.ore.length) {
    const ore = new THREE.InstancedMesh(box, emissive(T.neonOre, 0x22d3ee, 0.8), decor.ore.length);
    decor.ore.forEach((o, i) => {
      m.compose(v.set(o.x, o.y + 0.6, o.z), q, sc.set(1.6, 1.2, 1.6));
      ore.setMatrixAt(i, m);
    });
    group.add(ore);
  }

  // --- distant floor so the world never shows void
  const floor = new THREE.Mesh(
    new THREE.BoxGeometry(xMax - xMin + 3000, 8, 3000),
    new THREE.MeshLambertMaterial({ color: new THREE.Color(theme.grass).multiplyScalar(0.45) }),
  );
  floor.position.set((xMin + xMax) / 2, 5, 0);
  group.add(floor);

  group.traverse(o => {
    if (o.isInstancedMesh) {
      o.instanceMatrix.needsUpdate = true;
      if (o.instanceColor) o.instanceColor.needsUpdate = true;
      o.frustumCulled = false;
    }
  });
  return group;
}

// Sky, sun, moon, stars, blocky clouds, planets — everything that changes as
// the price (= altitude) climbs from the lava pit to outer space.
import * as THREE from 'three';
import { sampleAtmosphere, CLOUD_Y } from './zones.js';
import { lambert } from './textures.js';

export class Sky {
  constructor(scene, T, track) {
    this.scene = scene;
    this.group = new THREE.Group();
    scene.add(this.group);

    scene.fog = new THREE.Fog(0x9bc2ff, 40, 500);

    this.ambient = new THREE.AmbientLight(0xffffff, 0.75);
    this.sun = new THREE.DirectionalLight(0xfff3d6, 1.0);
    this.sun.position.set(120, 260, 80);
    scene.add(this.ambient, this.sun);

    // sun disc (blocky)
    this.sunDisc = new THREE.Mesh(
      new THREE.BoxGeometry(26, 26, 2),
      new THREE.MeshBasicMaterial({ color: 0xffe9a3, fog: false }),
    );
    this.group.add(this.sunDisc);

    // moon — only convincing high up
    this.moon = new THREE.Mesh(
      new THREE.BoxGeometry(34, 34, 4),
      new THREE.MeshBasicMaterial({ map: T.moon, fog: false, transparent: true, opacity: 0 }),
    );
    this.group.add(this.moon);

    // stars: fixed shell re-centered on the camera every frame
    const starCount = 900;
    const starPos = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i++) {
      const v = new THREE.Vector3().randomDirection().multiplyScalar(560 + Math.random() * 240);
      if (v.y < -60) v.y = -v.y;
      starPos.set([v.x, v.y, v.z], i * 3);
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
    this.stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
      color: 0xffffff, size: 1.6, sizeAttenuation: false,
      transparent: true, opacity: 0, fog: false, depthWrite: false,
    }));
    this.group.add(this.stars);

    // planets for the space zone
    this.planets = new THREE.Group();
    const planetDefs = [
      { c: 0xf97316, r: 18, p: [340, 160, -420] },
      { c: 0x60a5fa, r: 26, p: [-380, 220, 360] },
      { c: 0xa78bfa, r: 12, p: [240, 280, 380] },
    ];
    for (const d of planetDefs) {
      const m = new THREE.Mesh(
        new THREE.IcosahedronGeometry(d.r, 1),
        new THREE.MeshBasicMaterial({ color: d.c, fog: false, transparent: true, opacity: 0 }),
      );
      m.position.fromArray(d.p);
      m.userData.basePos = m.position.clone();
      this.planets.add(m);
    }
    // ringed planet
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(34, 4, 4, 24),
      new THREE.MeshBasicMaterial({ color: 0xfbbf24, fog: false, transparent: true, opacity: 0 }),
    );
    ring.rotation.x = Math.PI / 2.4;
    ring.position.copy(this.planets.children[0].position);
    ring.userData.basePos = ring.position.clone();
    this.planets.add(ring);
    this.group.add(this.planets);

    // blocky clouds along the whole track
    const xMax = track.controlPoints[track.controlPoints.length - 1].x;
    const cloudCount = Math.max(14, Math.floor(xMax / 90));
    const cloudGeo = new THREE.BoxGeometry(1, 1, 1);
    const slabs = [];
    for (let i = 0; i < cloudCount; i++) {
      const cx = Math.random() * (xMax + 240) - 120;
      const cz = (Math.random() - 0.5) * 320;
      const cy = CLOUD_Y + (Math.random() - 0.5) * 26;
      const parts = 2 + Math.floor(Math.random() * 3);
      for (let k = 0; k < parts; k++) {
        slabs.push({
          x: cx + (Math.random() - 0.5) * 26,
          y: cy + (Math.random() - 0.5) * 5,
          z: cz + (Math.random() - 0.5) * 20,
          sx: 18 + Math.random() * 26, sz: 12 + Math.random() * 18,
        });
      }
    }
    this.clouds = new THREE.InstancedMesh(
      cloudGeo,
      new THREE.MeshBasicMaterial({ map: T.cloud, transparent: true, opacity: 0.92 }),
      slabs.length,
    );
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), v = new THREE.Vector3();
    slabs.forEach((sl, i) => {
      m4.compose(v.set(sl.x, sl.y, sl.z), q, s.set(sl.sx, 4.2, sl.sz));
      this.clouds.setMatrixAt(i, m4);
    });
    this.clouds.instanceMatrix.needsUpdate = true;
    this.clouds.frustumCulled = false;
    this.group.add(this.clouds);

    // shooting star
    this.shooter = new THREE.Mesh(
      new THREE.BoxGeometry(9, 0.5, 0.5),
      new THREE.MeshBasicMaterial({ color: 0xffffff, fog: false, transparent: true, opacity: 0 }),
    );
    this.group.add(this.shooter);
    this.shootT = -3;

    this.skyColor = new THREE.Color();
  }

  update(dt, camPos, time) {
    const atm = sampleAtmosphere(camPos.y);
    this.skyColor.copy(atm.sky);
    this.scene.background = this.skyColor;
    this.scene.fog.color.copy(atm.fog);
    this.scene.fog.near = camPos.y > 255 ? 120 : 30;
    this.scene.fog.far = atm.fogFar;
    this.sun.intensity = atm.sun;
    this.ambient.intensity = atm.ambient;

    this.stars.material.opacity = atm.starAlpha;
    this.stars.position.copy(camPos);
    this.stars.rotation.y = time * 0.004;

    // celestial bodies track the camera horizontally so they feel infinitely far
    this.sunDisc.position.set(camPos.x + 320, Math.max(140, camPos.y + 120), camPos.z - 360);
    this.sunDisc.lookAt(camPos);
    this.sunDisc.material.color.setHex(camPos.y > 255 ? 0xfff7df : 0xffe9a3);

    const moonA = THREE.MathUtils.clamp((camPos.y - 230) / 60, 0, 1);
    this.moon.material.opacity = moonA;
    this.moon.position.set(camPos.x - 260, camPos.y + 150, camPos.z + 300);
    this.moon.lookAt(camPos);

    const spaceA = atm.spaceness;
    for (const p of this.planets.children) {
      p.material.opacity = spaceA * 0.95;
      p.position.set(
        camPos.x + p.userData.basePos.x,
        Math.max(p.userData.basePos.y, camPos.y - 80) + Math.sin(time * 0.07 + p.id) * 4,
        camPos.z + p.userData.basePos.z,
      );
    }

    // clouds fade out in deep space, drift slowly
    this.clouds.material.opacity = 0.92 * (1 - spaceA * 0.85);
    this.clouds.position.z = Math.sin(time * 0.01) * 8;

    // occasional shooting star up high
    if (atm.starAlpha > 0.6) {
      this.shootT += dt;
      if (this.shootT > 6 + (camPos.x % 5)) this.shootT = 0;
      if (this.shootT >= 0 && this.shootT < 1.1) {
        const k = this.shootT / 1.1;
        this.shooter.material.opacity = Math.sin(k * Math.PI);
        this.shooter.position.set(
          camPos.x - 200 + k * 420,
          camPos.y + 180 - k * 90,
          camPos.z - 240,
        );
        this.shooter.rotation.z = -0.21;
      } else {
        this.shooter.material.opacity = 0;
      }
    } else {
      this.shooter.material.opacity = 0;
    }
  }

  dispose() {
    this.scene.remove(this.group, this.ambient, this.sun);
  }
}

// DOM HUD: date/price readouts, zone label, mini chart with progress,
// headline toasts, ATH flash, ride-end summary.
import { fmtDate } from './billboards.js';

const MONTHS_FULL = ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE',
  'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'];

export function fmtMoney(v, currency = 'USD') {
  const sym = currency === 'USD' ? '$' : currency + ' ';
  if (v >= 1000) return sym + v.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (v >= 1) return sym + v.toFixed(2);
  return sym + v.toFixed(4);
}

export function fmtPct(p) {
  const v = p * 100;
  const sign = v >= 0 ? '+' : '';
  if (Math.abs(v) >= 10000) return `${sign}${(v / 1000).toFixed(1)}k%`;
  return `${sign}${v.toFixed(Math.abs(v) < 10 ? 1 : 0)}%`;
}

export class Hud {
  constructor() {
    this.el = {
      hud: document.getElementById('hud'),
      symbol: document.getElementById('hud-symbol'),
      date: document.getElementById('hud-date'),
      price: document.getElementById('hud-price'),
      zone: document.getElementById('hud-zone'),
      chart: document.getElementById('hud-chart'),
      toast: document.getElementById('hud-toast'),
      ath: document.getElementById('hud-ath'),
      hint: document.getElementById('hud-hint'),
    };
    this.toastUntil = 0;
    this.athUntil = 0;
    this.toastQueue = [];
    this.cinematic = false;
    this.speedFlashUntil = 0;
    this.speedLevel = 2;
    this.chartCtx = this.el.chart.getContext('2d');

    // click the minimap to jump to that point in history
    this.onSeek = null;
    this.hoverIndex = -1;
    this.el.chart.addEventListener('click', e => {
      const i = this.indexAtEvent(e);
      if (i >= 0 && this.onSeek) this.onSeek(i);
    });
    this.el.chart.addEventListener('mousemove', e => { this.hoverIndex = this.indexAtEvent(e); });
    this.el.chart.addEventListener('mouseleave', () => { this.hoverIndex = -1; });
  }

  /** Data point index under a mouse event on the minimap, or -1. */
  indexAtEvent(e) {
    if (!this.ride || !this.chartXY) return -1;
    const r = this.el.chart.getBoundingClientRect();
    const px = (e.clientX - r.left) * (this.el.chart.width / r.width);
    const n = this.ride.points.length;
    const f = (px - 4) / (this.el.chart.width - 8);
    return Math.max(0, Math.min(n - 1, Math.round(f * (n - 1))));
  }

  show(ride) {
    this.ride = ride;
    this.cinematic = false;
    this.el.hud.style.opacity = '1';
    this.toastQueue = [];
    this.toastUntil = 0;
    this.athUntil = 0;
    this.el.hud.classList.add('active');
    this.el.symbol.innerHTML = `${esc(ride.symbol)}<small>${esc(ride.name)}</small>`;
    this.el.hint.textContent = 'SPACE pause · paused: S screenshot · 1-4 speed · click map to time-travel · ESC station';
    this.speedLevel = 2;
    this.speedFlashUntil = 0;
    this.prepChart(ride);
    this.lastIndex = -1;
  }

  hide() {
    this.el.hud.classList.remove('active');
    this.el.toast.style.display = 'none';
    this.el.ath.style.display = 'none';
  }

  toggleCinematic() {
    this.cinematic = !this.cinematic;
    this.el.hud.style.opacity = this.cinematic ? '0' : '1';
  }

  flashSpeed(level) {
    this.speedLevel = level;
    this.speedFlashUntil = performance.now() + 1400;
  }

  prepChart(ride) {
    // pre-render the full log-price polyline to an offscreen canvas
    this.chartBase = document.createElement('canvas');
    this.chartBase.width = this.el.chart.width;
    this.chartBase.height = this.el.chart.height;
    const ctx = this.chartBase.getContext('2d');
    const W = this.chartBase.width, H = this.chartBase.height;
    ctx.fillStyle = '#0d1117';
    ctx.fillRect(0, 0, W, H);
    const pts = ride.points;
    let lmin = Infinity, lmax = -Infinity;
    for (const p of pts) {
      const l = Math.log(p.close);
      if (l < lmin) lmin = l;
      if (l > lmax) lmax = l;
    }
    const span = Math.max(1e-9, lmax - lmin);
    this.chartXY = i => [
      4 + (i / (pts.length - 1)) * (W - 8),
      H - 5 - ((Math.log(pts[i].close) - lmin) / span) * (H - 10),
    ];
    ctx.strokeStyle = '#3b4761';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) {
      const [x, y] = this.chartXY(i);
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    }
    ctx.stroke();
  }

  update(ride, index, zoneInfo, speed, paused = false, dt = 0) {
    if (paused) {
      // freeze toast/ATH timers while paused
      this.toastUntil += dt * 1000;
      this.athUntil += dt * 1000;
    }
    if (index !== this.lastIndex) {
      this.lastIndex = index;
      const p = ride.points[index];
      const [y, m, d] = p.date.split('-').map(Number);
      const day = p.timeLabel ? ` ${d}` : '';
      const time = p.timeLabel ? ` · ${esc(p.timeLabel)}` : '';
      this.el.date.innerHTML = `${MONTHS_FULL[m - 1]}${day} ${y}${time}<small>${esc(ride.symbol)} RIDE</small>`;
      const pct = p.close / ride.points[0].close - 1;
      this.el.price.innerHTML =
        `${fmtMoney(p.close, ride.currency)}<span class="pct ${pct >= 0 ? 'up' : 'down'}">${fmtPct(pct)} since start</span>`;
    }
    const speedFlash = performance.now() < this.speedFlashUntil ? ` · SPEED ${this.speedLevel}` : '';
    this.el.zone.innerHTML =
      `${zoneInfo.icon} ${zoneInfo.label}${speedFlash}<span class="speed">${Math.round(speed * 2.43)} MPH</span>`;

    // chart: base + played-overlay + dot
    const ctx = this.chartCtx;
    ctx.drawImage(this.chartBase, 0, 0);
    ctx.strokeStyle = '#fcd34d';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i <= index; i++) {
      const [x, y] = this.chartXY(i);
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    }
    ctx.stroke();
    const [dx, dy] = this.chartXY(index);
    ctx.fillStyle = '#fff';
    ctx.fillRect(dx - 2.5, dy - 2.5, 5, 5);

    // hover scrubber: vertical line + date of the point you'd jump to
    if (this.hoverIndex >= 0 && this.hoverIndex < ride.points.length) {
      const W = this.el.chart.width, H = this.el.chart.height;
      const [hx] = this.chartXY(this.hoverIndex);
      ctx.strokeStyle = 'rgba(255,255,255,.6)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(hx, 2);
      ctx.lineTo(hx, H - 2);
      ctx.stroke();
      ctx.fillStyle = '#fcd34d';
      ctx.font = 'bold 11px monospace';
      ctx.textAlign = hx > W / 2 ? 'right' : 'left';
      ctx.fillText(fmtDate(ride.points[this.hoverIndex].date), hx + (hx > W / 2 ? -5 : 5), 13);
      ctx.textAlign = 'left';
    }

    if (performance.now() > this.toastUntil) {
      if (this.toastQueue.length) this.showToast(this.toastQueue.shift());
      else this.el.toast.style.display = 'none';
    }
    if (performance.now() > this.athUntil) this.el.ath.style.display = 'none';
  }

  /** Queue a headline; stacked same-moment headlines display one after another. */
  toast(headline) {
    if (performance.now() > this.toastUntil) this.showToast(headline);
    else this.toastQueue.push(headline);
  }

  showToast(headline) {
    const s = headline.sentiment === 'pos' ? '#4ade80' : headline.sentiment === 'neg' ? '#f87171' : '#d4d4d8';
    this.el.toast.innerHTML =
      `<span class="toast-date">📰 ${esc(fmtDate(headline.date))}</span><br/><span style="color:${s}">${esc(headline.title)}</span>`;
    this.el.toast.style.display = 'block';
    this.toastUntil = performance.now() + (this.toastQueue.length ? 4200 : 6000);
  }

  flashATH() {
    this.el.ath.style.display = 'block';
    this.athUntil = performance.now() + 2600;
  }

  showSummary(ride) {
    const stats = ride.stats;
    const last = ride.points[ride.points.length - 1];
    const first = ride.points[0];
    const years = (new Date(last.date) - new Date(first.date)) / 31557600000;
    const grand = 1000 * (last.close / first.close);
    const rows = [
      ['RIDE', `${ride.symbol} (${fmtDate(first.date)} → ${fmtDate(last.date)})`],
      ['TOTAL RETURN', `<span class="${stats.totalReturn >= 0 ? 'up' : 'down'}">${fmtPct(stats.totalReturn)}</span>`],
      ['$1,000 INVESTED', `<span class="${grand >= 1000 ? 'up' : 'down'}">${fmtMoney(grand)}</span>`],
      ['PEAK ALTITUDE', `${fmtMoney(stats.max, ride.currency)} (${fmtDate(ride.points[stats.maxIndex].date)})`],
      ['MAX DRAWDOWN', `<span class="down">-${Math.round(stats.maxDrawdown * 100)}%</span>`],
      ['YEARS RIDDEN', years.toFixed(1)],
    ];
    document.getElementById('summary-title').textContent =
      stats.totalReturn >= 0 ? `YOU SURVIVED ${ride.symbol}!` : `${ride.symbol} TOOK YOUR LUNCH MONEY`;
    document.getElementById('summary-rows').innerHTML =
      rows.map(([k, v]) => `<div>${k}<span>${v}</span></div>`).join('');
    document.getElementById('summary').style.display = 'flex';
  }

  hideSummary() {
    document.getElementById('summary').style.display = 'none';
  }
}

function esc(s) {
  return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}
